css:
.cat-card{padding:16px;border-radius:var(--cat-size-radius-lg);background:var(--cat-color-surface-content);border:1px solid var(--cat-color-stroke-light);box-shadow:var(--cat-elevation-panel);font:400 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-hi)}
.cat-card.chip{background:var(--cat-color-surface-glass-chip);backdrop-filter:blur(var(--cat-blur-chip)) saturate(var(--cat-blur-saturate-chip));-webkit-backdrop-filter:blur(var(--cat-blur-chip)) saturate(var(--cat-blur-saturate-chip))}
.cat-card.dark{background:var(--cat-color-dark-player-bg);color:var(--cat-color-dark-player-ink);border-color:rgba(255,255,255,.14);box-shadow:var(--cat-elevation-float)}
.cat-card.float{background:var(--cat-semantic-float-a);backdrop-filter:blur(var(--cat-blur-float)) saturate(var(--cat-blur-saturate-float));-webkit-backdrop-filter:blur(var(--cat-blur-float)) saturate(var(--cat-blur-saturate-float));box-shadow:var(--cat-elevation-float),inset 0 1px 0 rgba(255,255,255,.7)}
.cat-toasts{position:fixed;top:16px;right:16px;z-index:var(--cat-depth-z-toast);display:flex;flex-direction:column;gap:8px;width:320px;max-width:calc(100vw - 32px)}
.cat-toast{display:flex;align-items:flex-start;gap:10px;padding:11px 12px;border-radius:var(--cat-size-radius-md);background:var(--cat-color-surface-menu);backdrop-filter:blur(var(--cat-blur-float));-webkit-backdrop-filter:blur(var(--cat-blur-float));border:1px solid var(--cat-color-stroke-menu);box-shadow:var(--cat-elevation-menu);font:400 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-hi);transition:opacity var(--cat-motion-med) ease,transform var(--cat-motion-med) var(--cat-motion-ease-out)}
.cat-toast .t-icon{flex:none;width:8px;height:8px;border-radius:50%;background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));margin-top:5px}
.cat-toast.success .t-icon{background:var(--cat-color-success)}
.cat-toast.danger .t-icon{background:var(--cat-color-danger-base)}
.cat-toast .t-close{margin-left:auto;background:none;border:none;color:var(--cat-color-ink-low);cursor:pointer;font-size:13px;line-height:1;padding:2px 4px;border-radius:4px}
.cat-toast .t-close:hover{background:rgba(0,0,0,.07);color:var(--cat-color-ink-hi)}
.cat-leaving{opacity:0!important;transform:translateY(6px)!important}
